create or replace function public.get_dispute_evidence_path(p_evidence_object_id uuid)returns text language plpgsql security definer set search_path=pg_catalog,public,private as $$declare v_path text;begin select eo.object_path into v_path from private.evidence_objects eo join public.dispute_evidence de on de.evidence_object_id=eo.id join public.result_disputes d on d.id=de.dispute_id where eo.id=p_evidence_object_id and(d.opened_by=public.current_player_id()or private.has_club_role(d.club_id,array['owner','score_official']::public.club_role[]));if v_path is null then raise exception using errcode='P0001',detail='NOT_FOUND';end if;return v_path;end$$;revoke all on function public.get_dispute_evidence_path(uuid)from public;grant execute on function public.get_dispute_evidence_path(uuid)to authenticated;
